import{_ as i,c as e,o as l,a2 as s}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"故障排除","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/troubleshooting.md","filePath":"zh-CN/guide/troubleshooting.md","lastUpdated":1793163976000}'),t={name:"zh-CN/guide/troubleshooting.md"};function o(r,a,n,p,h,d){return l(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to &quot;故障排除&quot;">​</a></h1><p>本页面汇总了 NueZip 在 macOS 上的常见问题及其解决方法。</p><h2 id="应用无法启动或启动时崩溃" tabindex="-1">应用无法启动或启动时崩溃 <a class="header-anchor" href="#应用无法启动或启动时崩溃" aria-label="Permalink to &quot;应用无法启动或启动时崩溃&quot;">​</a></h2><p>症状：NueZip 无法打开、立即崩溃，或显示意外错误。</p><p>可尝试的步骤：</p><ol><li>确保你的 macOS 版本满足最低要求（macOS 14 Sonoma 或更高）。</li><li>退出并重新启动应用。</li><li>重启你的 Mac。</li><li>如果应用是从 GitHub Releases 下载的，请尝试下载最新的构建版本或经过公证的版本。</li><li>如果问题仍然存在，请收集日志（见下文）并提交 issue。</li></ol><h2 id="无法打开-rar-归档" tabindex="-1">无法打开 RAR 归档 <a class="header-anchor" href="#无法打开-rar-归档" aria-label="Permalink to &quot;无法打开 RAR 归档&quot;">​</a></h2><p>症状：NueZip 无法打开 <code>.rar</code> 文件，或显示错误。</p><p>检查清单：</p><ol><li>确保 RAR 文件未损坏。尝试使用其他工具（如 The Unarchiver）打开它。</li><li>多卷 RAR 归档必须包含所有分卷（<code>.part1.rar</code>、<code>.part2.rar</code> 等）。</li><li>带密码保护的 RAR 归档需要正确的密码。</li><li>支持 RAR5 格式。如果你使用的是较旧的 RAR 格式，请反馈给我们。</li></ol><h2 id="解压因密码错误而失败" tabindex="-1">解压因密码错误而失败 <a class="header-anchor" href="#解压因密码错误而失败" aria-label="Permalink to &quot;解压因密码错误而失败&quot;">​</a></h2><p>症状：解压失败，显示 &quot;密码错误&quot; 或解密错误。</p><p>检查清单：</p><ol><li>确认密码正确 — 密码区分大小写。</li><li>确保支持正确的加密类型（ZIP 为 AES-256）。</li><li>尝试从密码管理器重新输入密码。</li></ol><h2 id="finder-扩展不显示" tabindex="-1">Finder 扩展不显示 <a class="header-anchor" href="#finder-扩展不显示" aria-label="Permalink to &quot;Finder 扩展不显示&quot;">​</a></h2><p>症状：在 Finder 中右键点击归档时，没有显示 NueZip 的选项。</p><p>检查清单：</p><ol><li>启用扩展：系统设置 → 隐私与安全性 → 扩展 → Finder 扩展 → 启用 <strong>NueZip</strong>。</li><li>重启 Finder：在活动监视器中右键点击 Finder → 重新启动，或在终端中运行 <code>killall Finder</code>。</li><li>如果扩展仍然不出现，请重新安装应用。</li></ol><h2 id="许可证-购买未显示" tabindex="-1">许可证 / 购买未显示 <a class="header-anchor" href="#许可证-购买未显示" aria-label="Permalink to &quot;许可证 / 购买未显示&quot;">​</a></h2><p>症状：你已购买 NueZip，但它仍显示为试用版。</p><p>检查清单：</p><ol><li>确保你登录的是用于购买时相同的 Apple ID。</li><li>恢复购买：NueZip → 设置 → 许可证 → 恢复购买。</li><li>如果问题仍然存在，请联系支持。</li></ol><h2 id="如何收集调试日志" tabindex="-1">如何收集调试日志 <a class="header-anchor" href="#如何收集调试日志" aria-label="Permalink to &quot;如何收集调试日志&quot;">​</a></h2><p>为了帮助诊断问题，请从 NueZip 收集调试日志：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 将日志复制到桌面以便分享</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip/Data/Library/Logs/NueZip/nuezip.log</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Desktop/NueZip-Logs</span></span></code></pre></div><p>然后在 <a href="https://github.com/nuezip/nuezip/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 上提交 issue 并附上日志。</p><h2 id="权限相关问题" tabindex="-1">权限相关问题 <a class="header-anchor" href="#权限相关问题" aria-label="Permalink to &quot;权限相关问题&quot;">​</a></h2><p>如果某项功能请求权限，但授予权限后仍无法正常工作：</p><ol><li>授予权限后，退出应用并重新打开。</li><li>如有需要，使用 <code>tccutil</code> 重置权限提示（参见 <a href="./permissions.html">权限指南</a>）。</li></ol><h2 id="性能问题" tabindex="-1">性能问题 <a class="header-anchor" href="#性能问题" aria-label="Permalink to &quot;性能问题&quot;">​</a></h2><p>如果应用运行缓慢或无响应：</p><ol><li>关闭其他占用资源较多的应用。</li><li>尝试解压一个较小的归档以隔离问题。</li><li>如果性能随时间下降，请重启应用。</li></ol><h2 id="查看日志" tabindex="-1">查看日志 <a class="header-anchor" href="#查看日志" aria-label="Permalink to &quot;查看日志&quot;">​</a></h2><p>要排查崩溃或问题，应用日志是最有用的线索。在沙盒（App Store）构建版本中，请查看：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.nuezip/Data/Library/Logs/NueZip/nuezip.log</span></span></code></pre></div><h2 id="重置应用" tabindex="-1">重置应用 <a class="header-anchor" href="#重置应用" aria-label="Permalink to &quot;重置应用&quot;">​</a></h2><p>要重置设置并清除本地数据：</p><ol><li>退出 NueZip</li><li>移除容器（请注意 — 这会删除所有设置）：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip</span></span></code></pre></div><ol start="3"><li>重新打开 NueZip 并重新配置。</li></ol><h2 id="报告问题" tabindex="-1">报告问题 <a class="header-anchor" href="#报告问题" aria-label="Permalink to &quot;报告问题&quot;">​</a></h2><p>在提交 issue 时，请包含：</p><ul><li>macOS 版本（苹果菜单 → 关于本机）</li><li>NueZip 版本（NueZip → 关于）</li><li>复现步骤</li><li>日志（收集方法见 <a href="#查看日志">查看日志</a> 部分）</li></ul><p>这有助于维护者更快地定位和修复问题。</p>`,44)])])}const b=i(t,[["render",o]]);export{u as __pageData,b as default};
